package e.e.a;public final class CrashDiagnosticsTest {public static void main(String[] args){RuntimeException outer=new RuntimeException("cookie=user_session=secret https://example.invalid/?token=secret"),inner=new IllegalStateException("password");outer.initCause(inner);inner.initCause(outer);outer.setStackTrace(new StackTraceElement[]{new StackTraceElement("e.e.a.CachePack","completed","CachePack.java",12)});String text=CrashDiagnostics.trace(outer);if(!text.contains("RuntimeException")||!text.contains("IllegalStateException")||!text.contains("CachePack.completed"))throw new AssertionError("type and frames missing");if(text.contains("secret")||text.contains("password")||text.contains("cookie="))throw new AssertionError("exception messages leaked");if(text.length()>65536)throw new AssertionError("trace unbounded");System.out.println("Crash diagnostics: types/frames retained, messages excluded, cycles bounded");}}
